mapper.select:
SELECT p.performance_id AS performanceId, p.performance_title AS title, p.performance_date AS date, p.performance_img AS img FROM performance p WHERE p.genre_id = #{genreId} AND p.performance_deleted_at IS NULL AND p.status_id IN (1,2)
AND (p.performance_date, p.performance_id) > (#{cursor.lastDate}, #{cursor.lastId})
ORDER BY p.performance_date ASC, p.performance_id ASC LIMIT #{limit}

SELECT genre_id
FROM performance
WHERE performance_id = #{performanceId}

SELECT EXISTS (
    SELECT 1
    FROM performance_favorite
    WHERE member_id = #{memberId}
      AND performance_id = #{performanceId}
)
